      "content": "**定义/概念**\n细胞学说主要由施莱登和施旺提出，后来魏尔肖补充“细胞通过分裂产生新细胞”，其要点是一切动植物都由细胞发育而来、细胞是生命活动的基本单位。生命系统的结构层次由小到大依次是细胞、组织、器官、系统、个体、种群、群落、生态系统和生物圈。\n**核心过程/关键内容**\n细胞是生命系统中最基本的结构单位和功能单位，也是生命活动的基本单位；地球上最基本的生命系统就是细胞。生命系统的各个层次既相互联系又具有相对独立性，高层次中会出现低层次所不具备的新特征。\n**方法/思路**\n判断某对象属于哪个层次时，先看它是不是由细胞构成：病毒没有细胞结构，必须寄生在活细胞内才能增殖，所以病毒不属于生命系统的任何层次，但它的生命活动离不开细胞。\n**常考题型与考法**\n常见的考法是排列生命系统的结构层次、判断某一具体对象（如一片森林、一个池塘中的全部鲤鱼）所属的层次，以及用“生命活动离不开细胞”解释单细胞生物的运动、病毒的增殖等现象。\n**易错提示**\n容易错在把“最基本的生命系统”说成蛋白质或DNA，也容易把种群与群落混淆——种群强调同种生物的全部个体，群落强调一定区域内的所有生物。",
