      "content": "**定义/概念**\n细胞分为原核细胞和真核细胞，划分依据是细胞内有无核膜包被的细胞核。原核细胞没有核膜包被的细胞核，只有拟核，也没有除核糖体以外的多种细胞器；真核细胞有成形的细胞核和多种具膜细胞器。\n**核心过程/关键内容**\n常见的原核生物有细菌（如大肠杆菌、乳酸菌）、蓝细菌、支原体、衣原体和放线菌等；蓝细菌细胞内含有藻蓝素和叶绿素，能进行光合作用，但没有叶绿体。真核生物包括动物、植物、真菌和原生生物。两类细胞都以DNA作为遗传物质，都有细胞膜、细胞质和核糖体。\n**方法/思路**\n判断原核生物时抓住“名带杆、球、螺旋、弧”或属于蓝细菌、支原体、衣原体、放线菌这一类群，不能被“菌”字迷惑，酵母菌、霉菌都是真核生物；细胞统一性则从细胞膜、细胞质、DNA和核糖体四处入手。\n**常考题型与考法**\n常考原核生物与真核生物的辨析、蓝细菌与植物细胞的比较（有无叶绿体），以及“细胞的统一性表现在哪些方面”的列举题，多以选择题形式出现。\n**易错提示**\n不要把蓝细菌当成有叶绿体的植物，不要认为原核细胞没有任何细胞器（它有核糖体），也不要把病毒归入原核生物，病毒根本没有细胞结构。",
