      "content": "**定义/概念**\n光学显微镜的放大倍数是目镜与物镜放大倍数的乘积，放大的是物像的长度或宽度，不是面积。显微镜下观察到的物像是上下、左右均颠倒的倒像。\n**核心过程/关键内容**\n物镜有螺纹，镜头越长放大倍数越大；目镜没有螺纹，镜头越长放大倍数越小。使用步骤是取镜安放、对光、低倍镜观察、把要观察的物像移到视野中央、转动转换器换上高倍镜、用细准焦螺旋调焦，观察颜色深的材料时应适当调亮视野。\n**方法/思路**\n物像在哪一侧就向哪一侧移动玻片，例如物像偏向左上方就把玻片向左上方移动，即可把它移到视野中央。换用高倍镜后视野变暗、看到的细胞数目变少，此时只能调节细准焦螺旋，不能动粗准焦螺旋。\n**常考题型与考法**\n常考放大倍数的计算、由低倍镜换高倍镜后视野中细胞数目的变化、判断视野中污物所在的位置，以及显微镜使用步骤的排序题。\n**易错提示**\n不要以为放大倍数越大视野越亮；不要把目镜和物镜的长短规律弄反；不要忘记换高倍镜前必须先在低倍镜下把物像移到视野中央。",
