      "content": "**定义/概念**\n组成细胞的元素按含量分为大量元素和微量元素，其中C、H、O、N含量最多，C是构成细胞的最基本元素。组成细胞的化合物分为无机物（水和无机盐）和有机物（糖类、脂质、蛋白质、核酸）。\n**核心过程/关键内容**\n细胞鲜重中含量最多的化合物是水，含量最多的有机物是蛋白质；干重中含量最多的是蛋白质。组成细胞的元素在无机自然界中都能找到，没有一种是细胞特有的，这说明生物界与非生物界具有统一性，而元素含量上的差异又体现了两者的差异性。\n**方法/思路**\n鉴定生物组织中的有机物时按“选材—加试剂—看现象”的思路操作：还原糖与斐林试剂在50~65℃水浴加热条件下生成砖红色沉淀，蛋白质与双缩脲试剂反应呈紫色，脂肪可被苏丹Ⅲ染液染成橘黄色。\n**常考题型与考法**\n常考元素与化合物的种类和含量比较、有机物鉴定实验中试剂的选择与结果描述，以及“组成细胞的元素在无机自然界中都能找到说明了什么”这类结论表达题。\n**易错提示**\n不要用双缩脲试剂去检测还原糖，也不要忘记斐林试剂需要水浴加热；不要把砖红色说成红色。还要注意O在细胞鲜重中含量最多，而生命活动的最基本元素是C。",
