      "content": "**定义/概念**\n细胞中的水以自由水和结合水两种形式存在：自由水以游离形式存在，是良好的溶剂，参与运输和许多化学反应；结合水与细胞内的其他物质相结合，是细胞结构的重要组成成分。无机盐在细胞中大多以离子形式存在。\n**核心过程/关键内容**\n自由水与结合水的比值越大，细胞代谢越旺盛，但抗逆性越弱；比值降低则代谢减弱、抗寒抗旱能力增强。无机盐可参与构成复杂化合物，例如Mg是叶绿素的组成元素、Fe是血红蛋白的组成元素，此外还能维持细胞的渗透压和酸碱平衡。\n**方法/思路**\n分析生产生活中的现象时抓两个指标：种子晒干损失的主要是自由水，烘干损失的主要是结合水；缺钙会引起抽搐、钙过多则引起肌无力，说明无机盐离子必须维持在适宜浓度。\n**常考题型与考法**\n常考自由水与结合水比值的应用、无机盐功能的实例判断（如缺Mg叶片变黄、缺Fe引起贫血），以及种子储藏与萌发过程中水分变化的分析题。\n**易错提示**\n不要认为无机盐都以离子形式存在，有些无机盐是化合物的组成成分；不要把自由水和结合水的功能颠倒，也不要认为结合水越多代谢越旺盛。",
