      "content": "**定义/概念**\n糖类是细胞的主要能源物质，按其能否水解及水解产物分为单糖、二糖和多糖。单糖有葡萄糖、果糖、核糖和脱氧核糖等，二糖有蔗糖、麦芽糖和乳糖，多糖有淀粉、纤维素和糖原。脂质包括脂肪、磷脂和固醇三类。\n**核心过程/关键内容**\n植物细胞中的多糖是淀粉和纤维素，动物细胞中的储能多糖是糖原；淀粉和糖原都是储能物质，纤维素是构成植物细胞壁的成分。脂肪是细胞内良好的储能物质，还具有保温和缓冲作用；磷脂是构成细胞膜和多种细胞器膜的重要成分；固醇包括胆固醇、性激素和维生素D，胆固醇还参与血液中脂质的运输。\n**方法/思路**\n比较储能能力时抓住脂肪分子中氧含量少、氢含量多，氧化分解时释放的能量比等质量的糖类多，所以脂肪是主要的储能物质而糖类是主要的能源物质。\n**常考题型与考法**\n常考糖类和脂质的分类归属、单体与多聚体的对应关系，以及“细胞中的主要能源物质、主要储能物质、直接能源物质分别是什么”的辨析题。\n**易错提示**\n不要把纤维素当成储能物质，也不要混淆“主要能源物质是糖类”与“主要储能物质是脂肪”；蔗糖和乳糖都不是还原糖，不能与斐林试剂发生颜色反应。",
