      "content": "**定义/概念**\n核酸是细胞内携带遗传信息的物质，包括DNA和RNA两类，由核苷酸聚合而成。每个核苷酸由一分子磷酸、一分子五碳糖和一分子含氮碱基组成。\n**核心过程/关键内容**\nDNA中的五碳糖是脱氧核糖，碱基为A、T、G、C；RNA中的五碳糖是核糖，碱基为A、U、G、C，特有的碱基是U。真核细胞的DNA主要分布在细胞核中，线粒体和叶绿体中也含有少量DNA；RNA主要分布在细胞质中。\n**方法/思路**\n观察DNA和RNA在细胞中的分布时，用甲基绿和吡罗红混合染色剂处理细胞，结果是细胞核呈绿色、细胞质呈红色；做题时把颜色与核酸种类一一对应起来判断即可。\n**常考题型与考法**\n常考核苷酸的组成、核酸的基本单位与种类、甲基绿吡罗红染色结果的判断，以及“不同生物的遗传物质分别是什么”的辨析题。\n**易错提示**\n不要混淆“遗传物质”与“主要遗传物质”，真核生物和原核生物的遗传物质都是DNA，只有少数病毒以RNA为遗传物质；一个DNA分子由两条脱氧核苷酸链构成，RNA一般只有一条链。",
