      "content": "**定义/概念**\n减数分裂是进行有性生殖的生物产生成熟生殖细胞时进行的染色体数目减半的细胞分裂。特点是染色体只复制一次,细胞连续分裂两次,子细胞中染色体数目是原始生殖细胞的一半。\n**核心过程/关键内容**\n间期:DNA复制和有关蛋白质的合成,染色体数目不变,每条染色体含有两条姐妹染色单体。减数第一次分裂:前期同源染色体两两配对(联会)形成四分体,非姐妹染色单体之间常发生缠绕并交换相应片段;中期各对同源染色体排列在赤道板两侧;后期同源染色体分离,非同源染色体自由组合;末期形成两个次级性母细胞,染色体数目减半。减数第二次分裂:细胞内没有同源染色体,中期染色体着丝粒排列在赤道板上,后期着丝粒分裂、姐妹染色单体分开,最终形成4个子细胞。一个精原细胞产生4个精细胞(2种),一个卵原细胞产生1个卵细胞和3个极体(1种)。\n**方法/思路**\n识图判断时期的关键:看有无同源染色体、是否联会、着丝粒的位置、染色体是否均等分配。数量变化曲线要记牢:染色体数2N→N→2N→N;核DNA数2N→4N→2N→N;染色单体数0→4N→2N→0。判断减数第一次分裂看同源染色体分离,判断减数第二次分裂看无同源染色体且着丝粒分裂。\n**常考题型与考法**\n考分裂时期图像的判断与排序;考染色体、DNA、染色单体数量变化的坐标曲线;考配子种类计算——一个精原细胞产生2种4个精子,一个卵原细胞只产生1种1个卵细胞,而一个个体可产生2的n次方种配子;考异常配子的成因分析(减数第一次分裂同源染色体未分离,或减数第二次分裂姐妹染色单体未分离)。\n**易错提示**\n不要误以为着丝粒分裂是减数第一次分裂的标志——着丝粒分裂只发生在减数第二次分裂和有丝分裂。有丝分裂全过程都存在同源染色体,只是不联会、不分离。染色体数目减半发生在减数第一次分裂末期(同源染色体分开),而不是减数第二次分裂。",
