      "keywords": [
        "基因突变",
        "碱基替换",
        "移码突变",
        "不定向性",
        "镰状细胞贫血"
      ],
      "content": "**定义/概念**\nDNA分子中发生碱基的替换、增添或缺失,而引起的基因碱基序列的改变,叫作基因突变。基因突变是生物变异的根本来源,能产生新的基因即等位基因,为生物进化提供原始材料。\n**核心过程/关键内容**\n时间:主要发生在DNA复制时,即细胞分裂前的间期。原因:物理因素如紫外线、X射线及其他辐射;化学因素如亚硝酸盐、碱基类似物;生物因素如某些病毒。特点:普遍性、随机性(可发生在个体发育的任何时期和细胞的任何DNA上)、低频性、不定向性(可产生多种等位基因)、多害少利性。结果:产生等位基因。若突变发生在配子中,可通过有性生殖传递给后代;若发生在体细胞中,一般不能遗传,但植物体细胞发生的突变可通过无性繁殖传递。实例:镰状细胞贫血是血红蛋白β链基因中发生碱基替换,谷氨酸被缬氨酸取代;囊性纤维病是CFTR基因中缺失3个碱基,导致肽链中缺少一个苯丙氨酸。\n**方法/思路**\n分析突变的效应:碱基替换只改变一个密码子,由于密码子的简并性,氨基酸序列可能不变;碱基的增添或缺失往往引起移码突变,使突变位点之后的氨基酸序列全部改变,后果通常更严重。比较基因突变与基因重组时抓住两点:是否产生新基因,以及发生的时期与原因。\n**常考题型与考法**\n考基因突变的概念、原因、特点与实例;考碱基替换、增添、缺失对蛋白质影响的比较;考\"基因突变不一定改变生物性状\"的原因分析;考基因突变与生物进化的关系,即为进化提供原材料;考与减数分裂、基因表达结合的综合分析。\n**易错提示**\n基因突变不一定导致性状改变:密码子具有简并性,突变可能发生在非编码区或非关键位置,突变的效应还可能被其他基因补偿。基因突变具有不定向性,而自然选择是定向的。基因突变产生的是等位基因,不改变基因的数目和位置;基因数目或排列顺序的改变属于染色体变异。",
