      "content": "**定义/概念**\n遗传系谱图是用符号表示一个家族中某种遗传病发病情况的图示。分析系谱图的核心是先判断遗传方式,即显隐性以及基因位于常染色体还是性染色体上,再据此推断个体的基因型并计算概率。\n**核心过程/关键内容**\n判断显隐性:\"无中生有\"为隐性,即双亲都正常而子代出现患者,该病为隐性遗传病;\"有中生无\"为显性,即双亲都患病而子代出现正常个体,该病为显性遗传病。判断基因位置:隐性遗传看女患者,若女患者的父亲或儿子中有正常个体,则该病一定不是伴X染色体隐性遗传;显性遗传看男患者,若男患者的母亲或女儿中有正常个体,则该病一定不是伴X染色体显性遗传。若患者全为男性且代代相传,则可能是伴Y染色体遗传。若以上方法都不能确定,则需分情况讨论,如\"可能为常染色体显性或伴X染色体显性\"。\n**方法/思路**\n解题四步:第一步判断显隐性;第二步判断基因位于常染色体还是X染色体;第三步写出已知个体的基因型,以隐性纯合子作为突破口,即\"隐性突破法\";第四步计算概率,注意区分\"患病男孩\"与\"男孩患病\",已经出生的个体不再乘性别概率。涉及两种遗传病时分别计算再相乘,只患一种病等于\"甲患乙正常\"加\"甲正常乙患\"。\n**常考题型与考法**\n考遗传方式的判断,包括\"最可能\"的表述;考某个体的基因型推断及概率,如正常个体是杂合子的概率为2/3;考再生一个孩子患病或为患病男孩的概率;考两种遗传病组合的概率计算。\n**易错提示**\n\"无中生有\"为隐性、\"有中生无\"为显性只适用于单基因遗传病,多基因遗传病和染色体异常遗传病不适用。判断正常个体是杂合子的概率时要注意双亲基因型的限制,如双亲均为Aa时正常子代为AA或Aa,杂合子概率为2/3而不是1/2。伴X染色体隐性遗传中\"女患者的父亲和儿子一定患病\"是判断的关键依据,记错方向会导致整题失分。",
