      "keywords": [
        "渗透压",
        "缓冲对",
        "pH",
        "组织水肿",
        "稳态失调"
      ],
      "content": "**定义/概念**\n理化性质指细胞外液的温度、渗透压和酸碱度。渗透压是溶液中溶质微粒对水的吸引力,单位体积溶液中溶质微粒越多,渗透压越高,吸水能力越强。稳态失调指外界环境变化过于剧烈或自身调节功能出现障碍时,内环境的理化性质偏离正常范围,细胞代谢随之紊乱。\n**核心过程/关键内容**\n血浆渗透压由晶体渗透压和胶体渗透压共同构成,前者由无机盐决定,后者由血浆蛋白决定。当血浆蛋白因肾病、肝病或营养不良而减少时,血浆渗透压下降,水分滞留于组织液,出现组织水肿。血浆pH的稳定依赖缓冲对:乳酸等酸性物质进入血液时,主要由碳酸氢钠与之反应生成碳酸,碳酸再分解为二氧化碳经肺排出;碱性物质进入血液时则由碳酸等缓冲。肾脏通过排出酸性或碱性物质进一步调节,呼吸系统通过改变通气量调节二氧化碳排出量。组织水肿的常见原因还包括淋巴管阻塞导致淋巴回流受阻,以及过敏反应使毛细血管通透性增大。\n**方法/思路**\n解答pH或渗透压变化题,先明确\"哪种物质增多或减少\",再按缓冲对方向或水分流动方向逐步推导,注意呼吸系统和肾脏是两条并行的排出与调节途径。\n**常考题型与考法**\n常考给出血浆蛋白偏低、毛细淋巴管阻塞、过敏反应等情境,判断组织液增多与组织水肿;也考输氧、输液时生理盐水浓度为0.9%的原因,以及剧烈运动后血浆pH只轻微下降的原因分析。\n**易错提示**\n渗透压大小不取决于溶质分子的大小,而取决于微粒数目;0.9%的氯化钠溶液与血浆渗透压相当,输入蒸馏水会造成红细胞吸水破裂;pH稳定是缓冲物质与肺、肾共同作用的结果,不能只写缓冲对。",
