      "keywords": [
        "抗利尿激素",
        "醛固酮",
        "渗透压感受器",
        "肾小管",
        "水盐平衡"
      ],
      "content": "**定义/概念**\n水盐平衡指人体内水和无机盐的含量及比例保持相对稳定,是内环境稳态的重要内容。水盐平衡的调节中枢位于下丘脑,参与调节的主要激素是抗利尿激素和醛固酮。抗利尿激素由下丘脑神经分泌细胞合成,经垂体释放;醛固酮由肾上腺皮质分泌。\n**核心过程/关键内容**\n细胞外液渗透压升高时,下丘脑中的渗透压感受器受到刺激,一方面把兴奋传至大脑皮层产生渴觉,使人主动饮水;另一方面促使下丘脑合成并由垂体释放抗利尿激素,该激素作用于肾小管和集合管,促进对水的重吸收,使尿量减少,细胞外液渗透压下降。细胞外液渗透压降低时,抗利尿激素分泌减少,肾小管和集合管对水的重吸收减少,尿量增多。血钠含量降低或血钾含量升高时,肾上腺皮质分泌醛固酮增多,促进肾小管和集合管对钠离子的重吸收并促进钾离子分泌,从而维持血钠和血钾含量的平衡。水和无机盐的排出途径主要有肾脏排尿、皮肤排汗、肺呼出气体和消化道排便,其中肾脏是最主要的排出途径。\n**方法/思路**\n解答水盐调节题,先判断是渗透压变化还是血钠血钾变化,再选择相应激素作答。关于尿量的判断,记住\"抗利尿激素多则尿少、少则尿多\"。分析饮水不足、大量出汗、静脉注射生理盐水等情境时,要写清感受器、中枢、激素、靶器官和作用结果。\n**常考题型与考法**\n常考抗利尿激素的合成部位与释放部位的区别;考查大量出汗后尿量减少的原因;考查醛固酮的作用部位与效应;结合曲线考查血浆渗透压与抗利尿激素含量的同步变化。\n**易错提示**\n抗利尿激素由下丘脑合成、垂体释放,不能写成垂体合成;抗利尿激素促进的是水的重吸收,使人尿量减少;醛固酮调节的是钠钾平衡,与水的重吸收不是同一激素的作用;渴觉在大脑皮层形成。",
