      "keywords": [
        "疫苗",
        "器官移植",
        "免疫抑制剂",
        "抗原检测",
        "抗体检测"
      ],
      "content": "**定义/概念**\n免疫学的应用主要包括免疫预防、免疫诊断和免疫治疗三个方面。疫苗通常是灭活的或减毒的病原体,或者它们的成分,接种后能引起机体产生特异性免疫,使机体获得对相应传染病的抵抗力。器官移植是把一个健康的器官移植到患者体内的过程,其成败与供者与受者的组织相容性抗原是否一致密切相关。\n**核心过程/关键内容**\n接种疫苗后,机体产生相应的抗体和记忆细胞,当相同病原体再次入侵时,记忆细胞迅速增殖分化,产生更快更强的免疫反应,从而起到预防作用。许多疫苗需要多次接种,目的是使机体产生更多的抗体和记忆细胞,获得更持久的免疫力。免疫诊断常利用抗原与抗体特异性结合的原理,检测血液中是否存在某种病原体的抗原或相应抗体,如检测乙肝表面抗原或艾滋病病毒抗体。器官移植面临的主要问题是免疫排斥反应,移植的器官作为抗原会引发以细胞免疫为主的排斥反应,因此需要供者与受者的组织相容性抗原尽可能接近,并长期使用免疫抑制剂,但使用免疫抑制剂会降低患者的免疫能力,增加感染和患肿瘤的风险。\n**方法/思路**\n解答疫苗类问题,注意区分\"注射疫苗\"与\"注射抗体\"的不同:前者属于免疫预防,需要时间产生免疫记忆;后者属于被动输入抗体,见效快但不能持久。分析移植排斥问题,可从抗原差异、细胞免疫作用、免疫抑制剂利弊三方面展开。\n**常考题型与考法**\n常考疫苗接种后抗体含量变化曲线分析;考查多次接种与一次接种的差异;考查器官移植中组织相容性抗原的作用及免疫抑制剂的双刃剑效应;结合抗原抗体特异性结合考查免疫检测原理。\n**易错提示**\n疫苗本身不是抗体,接种疫苗属于免疫预防而非直接获得免疫力;注射抗体属于被动免疫,不能产生记忆细胞;免疫抑制剂能提高移植成活率,但会削弱整体免疫功能;移植排斥主要由细胞免疫引起,不是只与抗体有关。",
      "links": [
        "bio-x1-humoral-immunity",
        "bio-x1-cellular-immunity",
        "bio-x1-immune-disorders"
      ],
      "book": "选择性必修1",
