      "content": "**定义/概念**\n生态位是指一个物种在群落中的地位或作用,包括它所处的空间位置、占用资源的情况,以及与其他物种的关系等。\n**核心过程/关键内容**\n研究植物的生态位,通常要研究它的种群密度、植株高度以及与其他物种的关系等;研究动物的生态位,通常要研究它的栖息地、食物、天敌以及与其他物种的关系等。两个物种的生态位重叠越多,种间竞争就越激烈;长期共存于同一群落的物种往往通过生态位分化来减少竞争,例如取食部位不同、活动时间不同或利用的资源不同。\n**方法/思路**\n比较两个物种的生态位,找出重叠部分,据此判断竞争强度,再推测它们的数量变化趋势或能够共存的原因。\n**常考题型与考法**\n给出某种动物的栖息地、食性、天敌等信息,要求描述其生态位;分析外来物种入侵后本地物种生态位的变化;解释同一群落中多种生物能够长期共存的原因。\n**易错提示**\n生态位描述的是物种在群落中的地位或作用,只写食性是不完整的;生态位重叠不等于不能共存;外来物种入侵后常因缺少天敌而占据更宽的生态位,与本地物种的竞争加剧。",
