      "content": "**定义/概念**\n本实验通过调查土壤中小动物的种类和数量,研究土壤中小动物类群的丰富度,属于生态学中的抽样调查。\n**核心过程/关键内容**\n许多土壤动物身体微小、活动能力较强,不适于用样方法或标志重捕法,因此常用取样器取样法进行采集和调查。采集小动物可用诱虫器,它利用土壤动物趋暗、趋湿、避高温的习性,在灯泡加热的条件下使小动物向下落入收集瓶,瓶中的酒精可固定并保存标本;也可用镊子或吸虫器直接采集。统计丰富度常用两种方法:记名计算法适用于个体较大、种群数量有限的群落;目测估计法按预先确定的多度等级估计单位面积上个体的多少。\n**方法/思路**\n先随机选定样地取样,再分离、采集小动物,最后分类并统计种类和数量。实验应设置重复,尽量减小对样地的干扰。\n**常考题型与考法**\n选择采集方法和统计方法并说明理由;分析诱虫器中酒精的作用;评价取样方案是否随机、样本量是否足够;比较不同样地土壤动物丰富度的差异及原因。\n**易错提示**\n混淆记名计算法与目测估计法的适用范围;误用样方法调查土壤小动物;只统计个体总数而不统计种类数,丰富度指的是物种数目的多少。",
