      "content": "**定义/概念**\n本实验通过设置对照实验,探究土壤微生物对落叶等有机物的分解作用,实验的自变量是土壤中微生物的有无。\n**核心过程/关键内容**\n实验设计思路是取同种、等量的落叶分成两组:实验组的土壤进行灭菌处理,例如将土壤用塑料袋包好放在 60 ℃ 恒温箱中处理约 1 小时,对照组土壤不作处理;两组在相同且适宜的条件下放置一段时间后,比较落叶的分解程度。检测指标可用落叶的腐烂程度或失重率;若用淀粉糊作材料,可滴加碘液观察颜色变化。实验要遵循单一变量原则和对照原则,土壤的理化性质、温度、湿度等无关变量都应保持相同且适宜。\n**方法/思路**\n先明确自变量和因变量,再设计对照并控制无关变量;预期结果是实验组分解慢、对照组分解快,说明土壤微生物具有分解作用。\n**常考题型与考法**\n补充完善实验步骤;判断自变量、因变量和无关变量;分析灭菌处理的目的;根据实验结果得出结论并评价实验方案的严谨性。\n**易错提示**\n灭菌处理只杀死土壤中的微生物,应尽量不改变土壤的理化性质;实验组与对照组必须使用同种、等量的落叶;结论只能针对本实验现象,不能随意扩大适用范围。",
      "links": [],
      "book": "选择性必修2",
      "ch": "第3章 生态系统及其稳定性"
