      "content": "**定义/概念**\n生态工程是指人类应用生态学和系统学等学科的基本原理和方法,对人工生态系统进行分析、设计和调控,或对已被破坏的生态环境进行修复、重建,从而提高生态系统的生产力或改善生态环境的技术体系。其基本原理包括自生、循环、协调和整体。\n**核心过程/关键内容**\n自生原理要求通过提高生物多样性等方式增强生态系统的自我调节能力,实现系统的自组织、自我优化、自我调节和自我更新。循环原理指通过物质的循环利用,使前一环节产生的废物尽可能被后一环节利用,如无废弃物农业和沼气池。协调原理要求生物与环境、生物与生物之间相互协调,引种时需要考虑环境容纳量,种植密度不能超过环境承载力。整体原理指生态系统是自然、经济、社会的复合系统,建设时既要考虑自然生态规律,又要考虑经济和社会效益,如山水林田湖草沙一体化保护和修复。\n**方法/思路**\n判断实例体现的原理时看该措施主要解决什么问题:变废为宝体现循环,增加物种体现自生,控制数量和密度体现协调,兼顾经济与社会效益体现整体。\n**常考题型与考法**\n给出生态工程实例判断所依据的原理;分析沼气池、桑基鱼塘中物质和能量的利用方式;评价某项生态工程方案的合理性。\n**易错提示**\n一个实例可能同时体现多个原理,作答时应结合材料找准主要原理;循环原理强调的是物质循环利用而不是能量循环;协调原理既指生物之间,也包括生物与环境之间。",
      "links": [],
      "book": "选择性必修2",
      "ch": "第4章 人与环境"
