      "content": "**定义/概念**\n选择培养基是通过改变培养基成分,允许特定种类微生物生长,同时抑制或阻止其他种类微生物生长的培养基。微生物数量测定常用稀释涂布平板法和显微镜直接计数法。\n**核心过程/关键内容**\n选择培养的原理举例:在培养基中不加入氮源,可以选择出能固氮的微生物;以尿素为唯一氮源,可以选择出分解尿素的细菌,尿素分解产生的氨使培养基pH升高,加入酚红指示剂后菌落周围呈红色;加入青霉素可抑制细菌而选择出酵母菌和霉菌;改变培养条件也能起选择作用,如把培养基放在高温环境中培养可选择耐高温的微生物,教材中PCR所用的耐高温DNA聚合酶就是从热泉中的水生栖热菌中提取的。\n稀释涂布平板法计数:菌液梯度稀释后取0.1 mL涂布到平板上,培养后选择菌落数在30~300之间的平板计数,并至少设置3个重复平板取平均值。计算公式为每克或每毫升样品中的菌株数等于C除以V再乘M,其中C为某一稀释度下平板上的平均菌落数,V为涂布平板时所用稀释液的体积,M为稀释倍数。\n**方法/思路**\n计数题的解题顺序是确定稀释倍数、选取有效平板(菌落数在30~300之间)、代入公式计算,并说明统计结果往往比实际活菌数偏少。\n**常考题型与考法**\n常考选择培养基的设计与作用分析、统计结果比实际活菌数少的原因(两个或多个细胞连在一起时平板上只形成一个菌落)、显微镜直接计数法结果偏大的原因(死菌和活菌都被计入),以及实验的重复原则。\n**易错提示**\n稀释涂布平板法统计值偏小,显微镜直接计数法统计值偏大,二者不能混淆;菌落数少于30或多于300的平板应舍弃;涂布时稀释液体积要准确且涂布均匀;选择培养基上长出的微生物不一定是目的菌,还需要进一步鉴定。",
