      "keywords": [
        "微型繁殖",
        "作物脱毒",
        "人工种子",
        "细胞产物工厂化",
        "单倍体育种"
      ],
      "content": "**定义/概念**\n植物细胞工程的应用以植物组织培养技术为基础,主要包括微型繁殖、作物脱毒、人工种子、细胞产物的工厂化生产,还包括单倍体育种和突变体的利用等。\n**核心过程/关键内容**\n微型繁殖:取优良品种的组织进行组织培养,可在短期内大量繁殖,并能保持优良品种的遗传特性,不受季节和气候限制。\n作物脱毒:长期进行无性繁殖的植物容易被病毒感染,而茎尖附近的病毒极少甚至没有,因此常取茎尖进行组织培养获得脱毒苗。\n人工种子:以组织培养得到的胚状体、不定芽、顶芽、腋芽等为材料,外面包上人工薄膜制成,便于贮藏和运输。\n细胞产物的工厂化生产:通过愈伤组织或细胞悬浮培养生产次生代谢物,如紫草宁、人参皂苷、紫杉醇等。\n单倍体育种:取花药或花粉进行离体培养获得单倍体植株,再用秋水仙素处理使染色体数目加倍得到纯合子,能明显缩短育种年限。此外,愈伤组织细胞在培养过程中容易发生突变,可用于筛选优良突变体。\n**方法/思路**\n判断应用类型的思路是先明确目的:快速获得大量相同个体属于微型繁殖,去除病毒用茎尖脱毒,获得纯合子用单倍体育种,获得代谢产物用细胞培养。\n**常考题型与考法**\n常考应用与原理的匹配、为什么用茎尖脱毒、单倍体育种为什么能缩短育种年限、人工种子与天然种子的区别,以及与育种和基因工程的综合题。\n**易错提示**\n微型繁殖属于无性繁殖,后代遗传特性与亲本相同;脱毒苗不等于抗病毒品种,只是体内不带病毒;人工种子不是真正的种子,其中的胚是胚状体等;单倍体植株高度不育,必须经人工加倍才能用于育种;细胞产物工厂化生产利用的是细胞的代谢产物而不是完整植株。",
