      "content": "**定义/概念**\n动物细胞融合也称细胞杂交,是指两个或多个动物细胞结合形成一个细胞的过程,融合后形成的具有原来两个或多个细胞遗传信息的单核细胞称为杂交细胞。\n**核心过程/关键内容**\n诱导融合的方法有三类:物理法如电激;化学法如聚乙二醇(PEG);生物法即用灭活的病毒(如灭活的仙台病毒)诱导,这是动物细胞融合特有的方法,原理是病毒表面的某些物质能促使细胞膜发生融合。灭活是指用物理或化学手段使病毒失去感染能力,但保留其诱导细胞融合的能力。\n基本过程:把两种细胞混合,加入诱导剂或施加物理因素,部分细胞发生融合,先形成双核或多核细胞,进而形成单核的杂交细胞,再通过筛选获得所需的杂交细胞。\n**方法/思路**\n与植物体细胞杂交比较:植物细胞需先用纤维素酶和果胶酶去除细胞壁获得原生质体,动物细胞不需要去壁;两者都可用物理法和化学法诱导,但只有动物细胞融合可用灭活病毒诱导。\n**常考题型与考法**\n常考诱导方法的归类与判断、灭活的病毒为什么能诱导融合、灭活后病毒失去什么和保留什么,以及与单克隆抗体制备流程衔接的题目。\n**易错提示**\n灭活的对象是病毒而不是细胞;融合后得到的杂交细胞遗传物质来自两个或多个细胞;动物细胞融合与植物体细胞杂交的意义相同,都是克服远缘杂交不亲和的障碍;该技术最重要的应用是制备单克隆抗体。",
