      "content": "**定义/概念**\n由单个B淋巴细胞克隆产生的、针对单一抗原决定簇的抗体称为单克隆抗体。与从血清中提取的传统抗体相比,单克隆抗体特异性强、灵敏度高,并能大量制备,它的制备依赖动物细胞融合技术和动物细胞培养技术。\n**核心过程/关键内容**\n制备流程:用特定抗原多次免疫小鼠;从免疫小鼠的脾脏中取出能产生所需抗体的B淋巴细胞;把B淋巴细胞与能在体外无限增殖的骨髓瘤细胞融合,常用灭活的病毒、PEG或电激诱导;第一次筛选用特定的选择培养基,只有杂交瘤细胞能存活,未融合的B淋巴细胞不能无限增殖,未融合的骨髓瘤细胞及同种细胞融合形成的细胞不能产生所需抗体;第二次筛选经克隆化培养和抗体检测,选出能分泌所需抗体的杂交瘤细胞;把杂交瘤细胞在体外培养液中培养,或注射到小鼠腹腔内增殖;最后从培养液或小鼠腹水中提取单克隆抗体。\n**方法/思路**\n流程题按免疫、取B淋巴细胞、融合、两次筛选、扩大培养、提取的顺序作答;注意区分两次筛选,第一次筛掉的是不能存活的细胞,第二次筛出的是能产生所需抗体的细胞。\n**常考题型与考法**\n常考流程填空与排序、为什么选用骨髓瘤细胞、两次筛选的目的与结果、生物导弹的组成(单克隆抗体连接放射性同位素或化学药物)及其导向作用。\n**易错提示**\nB淋巴细胞不能无限增殖,骨髓瘤细胞不能产生抗体,只有杂交瘤细胞兼具两种特性;第一次筛选用的是选择培养基而不是抗原和抗体杂交;单克隆抗体来自杂交瘤细胞,不是直接来自小鼠血清;单克隆抗体特异性强是因为它只针对一种抗原决定簇。",
