      "keywords": [
        "精子获能",
        "卵母细胞成熟",
        "受精",
        "卵裂",
        "囊胚"
      ],
      "content": "**定义/概念**\n胚胎工程是对动物早期胚胎或配子进行的多种显微操作和处理技术,其理论基础是哺乳动物受精和早期胚胎发育的规律。受精是精子与卵细胞结合形成受精卵的过程,受精完成的标志是雌、雄原核融合。\n**核心过程/关键内容**\n受精前的准备:精子必须在雌性动物生殖道内发生生理变化后才能获得受精能力,称为精子获能;采集的卵母细胞需要体外人工培养到减数第二次分裂中期才具备受精能力。\n受精过程:精子穿越放射冠和透明带,顶体释放的酶溶解卵丘细胞间的物质和透明带;精子接触卵细胞膜,卵细胞膜发生反应阻止其他精子进入,防止多精入卵;精子入卵后形成雄原核,卵细胞完成减数第二次分裂形成雌原核;雌、雄原核融合,受精完成。\n早期胚胎发育:受精卵经卵裂(有丝分裂,细胞数目增加但胚胎总体积基本不变)形成桑葚胚(约32个细胞,形似桑葚),再形成囊胚(出现囊胚腔,细胞分化为内细胞团和滋养层,内细胞团将来发育成胎儿的各种组织,滋养层将来发育成胎膜和胎盘),进一步发育为原肠胚(形成外、中、内三个胚层)。\n**方法/思路**\n判断发育阶段抓两个标志,即是否出现囊胚腔和是否出现三个胚层;分析受精过程要抓两个准备(精子获能、卵母细胞成熟)和防止多精入卵的机制。\n**常考题型与考法**\n常考受精过程与胚胎发育阶段的排序、卵裂期细胞数目和胚胎总体积的变化、囊胚各部分将来的发育方向、透明带反应与卵细胞膜反应的作用。\n**易错提示**\n精子获能和卵母细胞成熟培养是受精的必要条件;卵裂属于有丝分裂而不是减数分裂;胚胎移植一般选用桑葚胚或囊胚;内细胞团发育成胎儿的各种组织,滋养层发育成胎膜和胎盘,二者不能混淆;卵裂期有机物总量减少。",
