      "core": 4,
      "keywords": [
        "超数排卵",
        "同期发情",
        "胚胎移植",
        "胚胎分割",
        "内细胞团"
      ],
      "content": "**定义/概念**\n胚胎移植是把雌性动物体内的早期胚胎(或体外培养得到的早期胚胎)移植到同种的、生理状态相同的其他雌性动物体内,使之继续发育成新个体的技术,是胚胎工程技术的最后一道工序。胚胎分割是采用机械方法把早期胚胎切割成2等份、4等份或8等份等,经移植获得同卵双胎或多胎的技术。\n**核心过程/关键内容**\n体外受精:对实验动物用促性腺激素处理使其超数排卵,再采集卵母细胞;精子经获能处理后与卵母细胞在获能溶液或专用受精溶液中完成受精;受精卵在体外培养到桑葚胚或囊胚。\n胚胎移植:对供体和受体母畜进行同期发情处理,使二者生殖器官的生理变化相同;对供体母畜进行超数排卵处理;配种或人工授精;用特制的装置从供体母畜的子宫或输卵管中冲出早期胚胎,并检查胚胎的质量和发育阶段;把胚胎移入受体母畜的子宫内;受体母畜妊娠并分娩。\n胚胎分割:选择发育良好、形态正常的桑葚胚或囊胚,用显微操作仪和分割针进行分割;分割囊胚时一定要把内细胞团均等分割,否则会影响分割后胚胎的恢复和进一步发育。\n**方法/思路**\n胚胎移植的实质是早期胚胎在相同生理环境条件下空间位置的转移:后代的遗传特性由供体和与之配种的个体决定,受体只提供发育环境,因此受体母畜的遗传特性不影响后代。\n**常考题型与考法**\n常考流程填空与排序、同期发情和超数排卵所用的激素及目的、受体母畜对后代遗传特性有无影响的简答、胚胎分割后代相同的原因以及性别鉴定的取样部位。\n**易错提示**\n同期发情处理的对象包括供体和受体,超数排卵处理只针对供体;冲出的胚胎不能直接移植,需要检查质量和发育阶段;囊胚分割时内细胞团分割不均等会导致后代发育不良;胚胎分割获得的后代遗传物质相同,属于无性繁殖;性别鉴定取样应取滋养层细胞而不是内细胞团。",
