      "keywords": [
        "基因文库",
        "cDNA文库",
        "人工合成",
        "目的基因",
        "核酸分子杂交"
      ],
      "content": "**定义/概念**\n目的基因主要指编码蛋白质的基因,如抗虫基因、抗病基因、人胰岛素基因等。筛选和获取目的基因是基因工程基本操作程序的第一步。\n**核心过程/关键内容**\n常用获取途径:从基因文库中获取,把生物的全部或部分基因导入受体菌保存,可构建基因组文库(含有内含子等全部序列)或cDNA文库(由mRNA反转录得到,不含内含子);利用PCR技术扩增目的基因,前提是已知目的基因的一段核苷酸序列以便设计引物;通过化学方法人工合成,适用于序列已知且较短的基因;也可以从其他生物中直接获取或对已有基因进行改造。\n筛选目的基因常用核酸分子杂交技术,用带标记的DNA探针与文库中的DNA杂交,检测是否存在目标序列。\n**方法/思路**\n选择获取方法的思路:序列已知且较短可人工合成;已知一段序列可设计引物进行PCR扩增;需要真核生物用于表达的编码序列时常用cDNA文库;研究基因的调控序列则需要基因组文库。\n**常考题型与考法**\n常考获取途径的判断与比较、基因组文库与cDNA文库的区别(是否含内含子、基因的完整性与数量)、为什么要先知道一段核苷酸序列,以及目的基因来源的分析。\n**易错提示**\n基因组文库中的基因含有内含子,cDNA文库中的基因不含内含子;原核细胞不能识别真核基因中的内含子,因此用原核细胞表达真核基因时常选择cDNA;PCR扩增需要一对引物,不能只设计一个;基因文库要借助受体菌保存,不是直接保存DNA片段。",
