      "content": "**定义/概念**\n生殖性克隆是指把克隆技术用于繁殖人,即通过体细胞核移植等技术获得人的胚胎并把它植入母体,使其发育成婴儿;治疗性克隆是指利用克隆技术获得胚胎干细胞或组织,用于治疗疾病。二者都与人的克隆有关,但目的和伦理性质完全不同。\n**核心过程/关键内容**\n治疗性克隆的思路:把病人的体细胞核移入去核的卵母细胞中,获得早期胚胎,再从早期胚胎中提取胚胎干细胞,通过定向诱导使其分化成所需的细胞或组织,用于治疗疾病;由于细胞核来自病人自身,移植后一般不发生免疫排斥反应。\n我国的立场:禁止生殖性克隆人,不反对治疗性克隆;不赞成、不允许、不支持、不接受任何生殖性克隆人的实验。理由是生殖性克隆人违反人类伦理道德,冲击现有的社会伦理体系;克隆人可能存在严重的生理缺陷,也可能被当作工具利用。\n相关伦理问题还涉及人的尊严、隐私、家庭关系、后代权益以及克隆技术被滥用等。\n**方法/思路**\n区分概念抓目的:以繁殖人为目的的是生殖性克隆;以治疗疾病为目的、不把胚胎植入母体的是治疗性克隆。回答立场题要写清我国禁止生殖性克隆人、不反对治疗性克隆的态度和理由。\n**常考题型与考法**\n常考概念辨析选择题、观点评述题、为什么禁止生殖性克隆人、治疗性克隆的优点(一般不发生免疫排斥反应)等简答。\n**易错提示**\n我国的立场是禁止生殖性克隆人,而不是禁止一切克隆技术;治疗性克隆与生殖性克隆的关键区别在于是否把胚胎植入母体、是否以生育为目的;克隆技术可以用于治疗疾病,但不能用于克隆人;胚胎的获得和处置涉及伦理争议,不能任意进行。",
