      "content": "**定义/概念**\n生物武器是指以生物战剂(致病菌、病毒、生化毒剂等)杀伤人、畜和毁坏农作物的武器。它具有致病力强、传染性强、传播途径多、危害时间长、不易被发现和防护等特点,因而被国际公约禁止。\n**核心过程/关键内容**\n常见的生物战剂包括细菌(如炭疽杆菌、鼠疫杆菌)、病毒(如天花病毒)、立克次氏体、衣原体以及真菌和某些生物毒素等。使用生物武器会造成大范围传染病流行,对平民和生态环境造成长期危害。\n1972年,国际社会签署了《禁止生物武器公约》,我国于1984年加入该公约。《公约》规定缔约国不得发展、生产和储存生物武器,并应销毁现有的生物武器。\n维护生物安全需要:加强国境卫生检疫,做好传染病的监测与防控,严格管理病原微生物菌(毒)种和实验室,禁止生物武器的研发与扩散,加强国际合作与法律约束。\n**方法/思路**\n回答如何防止生物武器的问题,可以从国际公约与立法、监测与检疫、菌种和实验室管理、科学研究伦理、国际合作等方面组织答案。\n**常考题型与考法**\n常考生物武器的特点与危害、常见生物战剂的种类、《禁止生物武器公约》的内容与我国的立场,以及结合生物安全(如实验室管理)的综合题。\n**易错提示**\n生物武器不仅针对军事人员,也会危害平民和生态环境;生物武器包括病原微生物和生物毒素,不限于细菌;我国是《禁止生物武器公约》的缔约国,坚决反对生物武器;生物安全防护不等于禁止一切微生物研究,关键在于规范管理。",
